import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import comp from './main.js';

const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp/Callout',
};

const basicArgs = {
  title: 'Callout heading',
  body: 'Callout content. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nam ac nunc neque. Praesent posuere lobortis purus, ac laoreet est volutpat in.',
};

const basicHtml = await squiz.markup(basicArgs);

export const Basic = {
  render: (args) => squiz(args),
  args: basicArgs,
  argTypes: {
    title: { control: 'text' },
    body: { control: 'text', description: 'Raw HTML (FormattedText). Supports <p>, <ul>/<ol>, <strong>, etc.' },
  },
  parameters: {
    docs: { source: { code: basicHtml, language: 'html', type: 'code' } },
  },
};

const richContentArgs = {
  title: 'Getting Started Guide',
  body: '<p>Follow these steps to get started with the NTG Design System:</p><ol><li>Install the package using npm or yarn</li><li>Import the theme CSS in your application</li><li>Import components as needed</li><li>Refer to the documentation for component APIs</li></ol><p><strong>Note:</strong> Callout is a text-only component and does not support icons.</p>',
};
const richContentHtml = await squiz.markup(richContentArgs);

export const RichContent = {
  render: () => squiz(richContentArgs),
  parameters: {
    docs: { source: { code: richContentHtml, language: 'html', type: 'code' } },
  },
};

const longContentArgs = {
  title: 'Accessibility Guidelines',
  body: 'The NTG Design System is committed to providing accessible components that meet WCAG 2.1 AA standards. All components include proper ARIA attributes, keyboard navigation support, and semantic HTML. We test with screen readers and ensure high contrast mode compatibility. When using callouts, ensure that the information is also conveyed through text and not color alone. This helps users with visual impairments or color blindness understand the content.',
};
const longContentHtml = await squiz.markup(longContentArgs);

export const LongContent = {
  render: () => squiz(longContentArgs),
  parameters: {
    docs: { source: { code: longContentHtml, language: 'html', type: 'code' } },
  },
};

const shortContentArgs = {
  title: 'Quick Note',
  body: 'This is a brief callout with minimal content.',
};
const shortContentHtml = await squiz.markup(shortContentArgs);

export const ShortContent = {
  render: () => squiz(shortContentArgs),
  parameters: {
    docs: { source: { code: shortContentHtml, language: 'html', type: 'code' } },
  },
};
