function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export default {
  async main(input = {}) {
    const {
      title = 'Callout heading',
      body = 'Callout content. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nam ac nunc neque. Praesent posuere lobortis purus, ac laoreet est volutpat in.',
    } = input;

    return /*html*/`
<div class="callout">
  <div class="callout__border"></div>
  <div class="callout__content">
    <div class="callout__header">
      <div class="callout__text">
        <h3 class="callout__title" data-sq-field="title">${esc(title)}</h3>
        <div class="callout__body" data-sq-field="body">${body}</div>
      </div>
    </div>
  </div>
</div>
`;
  },
};
